import { setRelation, setTerminals, type Prec, type Rel } from './precedence'
import type { ProjectData } from './project'

// G_expr2: E → E+E | E*E | (E) | i, * above +, both left-associative.
const EXAMPLE_TERMINALS = ['i', '+', '*', '(', ')']
// Row = terminal on the stack, columns in the order i + * ( ) $; '.' = empty cell.
const EXAMPLE_TABLE: Record<string, string> = {
  i: '. > > . > >',
  '+': '< > < < > >',
  '*': '< > > < > >',
  '(': '< < < < = .',
  ')': '. > > . > >',
  $: '< < < < . .',
}

function examplePrec(): Prec {
  const cols = [...EXAMPLE_TERMINALS, '$']
  let prec = setTerminals(
    { terminals: [], cells: {}, rules: 'E -> E + E\nE -> E * E\nE -> ( E )\nE -> i', input: 'i + i * i' },
    EXAMPLE_TERMINALS,
  )
  for (const [row, rels] of Object.entries(EXAMPLE_TABLE)) {
    rels.split(' ').forEach((r, c) => {
      if (r !== '.') prec = setRelation(prec, row, cols[c], r as Rel)
    })
  }
  return prec
}

/** Does the precedence section hold anything (terminals, relations, rules, input) that the example would overwrite? */
export function hasPrecTable(data: ProjectData) {
  const p = data.prec
  return Boolean(p.terminals.length || Object.keys(p.cells).length || p.rules.trim() || p.input.trim())
}

/** Replaces the whole precedence section (terminals, table, rules, input) with the G_expr2 example. */
export function loadPrecExample(data: ProjectData): ProjectData {
  return { ...data, prec: examplePrec() }
}
